"""Explain quantity readiness using the source-bound stock assessment."""
CSS='''
.po-quantity-review{margin:14px 0;padding:12px;background:#eff5ff;border:1px solid #bfd2ed;border-radius:8px}.po-quantity-review h3{font-size:14px!important;margin:0 0 10px}.po-quantity-review dl{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.po-quantity-review dl>div{background:white;padding:8px;border-radius:5px}.po-quantity-review dt{font-size:12px}.po-quantity-review dd{margin:5px 0 0;font-size:17px;font-weight:bold}.po-quantity-review li{margin:8px 0;font-size:13px;line-height:1.5}.po-quantity-review .po-quantity-scope{font-size:12px;line-height:1.5}
'''
JS=r'''
function renderPurchaseQuantityReview(parent,r){
 const box=document.createElement('section');box.className='po-quantity-review';box.dataset.quantityAssessment=r.quantity_assessment;const title=document.createElement('h3');title.textContent=r.simulation_readiness==='COMPLETE_HYPOTHETICAL'?'CANTIDAD Y STOCK · DATOS COMPLETOS PARA SIMULAR':'CANTIDAD Y STOCK · REFERENCIAS Y DATOS PENDIENTES';box.append(title);
 const note=document.createElement('p');note.className='po-quantity-scope';note.textContent=r.message;box.append(note);
 const metrics=document.createElement('dl');function metric(label,value){const d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;d.append(dt,dd);metrics.append(d)}
 metric('Cantidad de la propuesta',r.purchase_quantity!==null&&r.purchase_quantity!==undefined?stockNumber(r.purchase_quantity)+' '+r.unit:'Pendiente');
 if(r.inventory){metric('Disponible al '+stockDate(r.inventory.as_of_date),stockNumber(r.inventory.available)+' '+r.unit);metric('Reservado, ya descontado',stockNumber(r.inventory.reserved)+' '+r.unit);const source=document.createElement('p');source.className='po-quantity-scope';source.textContent='Fuente de inventario: '+(r.inventory.source||'Datos vinculados')+'. No representa automáticamente el stock del día del pedido.';box.append(source)}
 if(r.minimum){metric('Mínimo de referencia',stockNumber(r.minimum.value)+' '+r.unit);if(r.minimum.gap_at_inventory!==null)metric('Falta hasta el mínimo al corte',stockNumber(r.minimum.gap_at_inventory)+' '+r.unit);const basis=document.createElement('p');basis.className='po-quantity-scope';basis.textContent='Origen del mínimo: '+({MANUAL:'introducido en Stock',WORKBOOK:'libro activo',AUTOMATIC:'referencia automática del historial',UNCONFIGURED:'sin configurar'}[r.minimum.source]||r.minimum.source)+'. Este valor no es una cantidad óptima de compra.';box.append(basis)}
 if(r.coverage){metric('Cobertura al '+stockDate(r.coverage.as_of_date),r.coverage.status==='FINITE'?stockNumber(r.coverage.coverage_days)+' días':'Consumo previsto cero');metric('Consumo previsto',stockNumber(r.coverage.daily_demand)+' '+r.unit+'/día');if(r.coverage.lead_time_days!==null&&r.coverage.lead_time_days!==undefined)metric('Plazo de entrega de referencia',stockNumber(r.coverage.lead_time_days)+' días');if(r.coverage.covers_lead_time_at_inventory===false){const risk=document.createElement('p');risk.className='po-quantity-scope';risk.textContent='La cobertura del inventario de referencia es inferior al plazo de entrega. Revisa riesgo de rotura y calendario; no se ha proyectado todavía la recepción de esta compra.';box.append(risk)}const basis=document.createElement('p');basis.className='po-quantity-scope';basis.textContent='Cálculo del motor de stock con la previsión vinculada hasta '+stockDate(r.coverage.valid_to)+'. Cobertura del inventario de referencia; no es cobertura después de esta compra.';box.append(basis)}box.append(metrics);
 if(r.simulation_covered){const covered=document.createElement('details'),heading=document.createElement('summary');heading.textContent='Datos cubiertos por la hipótesis · 5 grupos';covered.append(heading);const ul=document.createElement('ul');for(const text of r.simulation_covered){const li=document.createElement('li');li.textContent=text;ul.append(li)}covered.append(ul);box.append(covered)}
 const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=r.simulation_readiness==='COMPLETE_HYPOTHETICAL'?'Para pasar de hipótesis a datos contrastados · '+(r.missing||[]).length+' comprobaciones':'Qué falta para justificar la cantidad · '+(r.missing||[]).length+' comprobaciones';details.append(summary);const list=document.createElement('ul');for(const item of r.missing||[]){const li=document.createElement('li');li.dataset.quantityMissing=item.code;li.textContent=item.message;list.append(li)}details.append(list);box.append(details);
 const button=document.createElement('button');button.type='button';button.textContent='Consultar inventario y mínimos en Stock';button.onclick=()=>view('stock');box.append(button);parent.append(box);
}
'''
